  public void ProgressionInitialize(){bool existingSave=!smoke&&PlayerPrefs.HasKey("Vault.Progression.v1");if(!smoke&&PlayerPrefs.HasKey("Vault.Progression.v1")){try{var s=JsonUtility.FromJson<ProgressSave>(PlayerPrefs.GetString("Vault.Progression.v1"));DungeonIndex=Mathf.Clamp(s.dungeon,0,2);HighestUnlocked=Mathf.Clamp(s.unlocked,0,2);Credits=Mathf.Max(0,s.credits);shopCycle=s.cycle;SelectedStageId=s.hasSelectedStage?Mathf.Clamp(s.stage,0,ExpeditionMap.StageCount-1):-1;ExpeditionTokens=Mathf.Max(0,s.tokens);ModuleCapacityTier=Mathf.Clamp(s.moduleCapacityTier,0,10);if(s.clearedStages!=null)foreach(int id in s.clearedStages)if(id>=0&&id<ExpeditionMap.StageCount&&!clearedExpeditionStages.Contains(id))clearedExpeditionStages.Add(id);if(s.artifacts!=null)foreach(var a in s.artifacts)if(a!=null&&!string.IsNullOrEmpty(a.id)&&ArtifactInventory.Count<ArtifactCapacity)ArtifactInventory.Add(a);if(s.equipped!=null)for(int i=0;i<Math.Min(2,s.equipped.Length);i++)EquippedArtifacts[i]=ArtifactInventory.Find(a=>a.id==s.equipped[i]);if(s.purchased!=null)shopPurchased.AddRange(s.purchased);}catch(Exception e){Debug.LogWarning("Progression load failed: "+e.GetType().Name);}}DebtSkillsInitialize();if(!existingSave){var starter=ArtifactCatalog.CreateCatalog(ModuleProductCatalog.Get(0,0).id,Rarity.Common,1);ArtifactInventory.Add(starter);EquippedArtifacts[0]=starter;SaveProgression();}CreateShopStock();}
  void SaveProgression(){if(smoke)return;PlayerPrefs.SetString("Vault.Progression.v1",JsonUtility.ToJson(new ProgressSave{dungeon=DungeonIndex,unlocked=HighestUnlocked,credits=Credits,cycle=shopCycle,stage=SelectedStageId,hasSelectedStage=SelectedStageId>=0,tokens=ExpeditionTokens,moduleCapacityTier=ModuleCapacityTier,clearedStages=clearedExpeditionStages,artifacts=ArtifactInventory,equipped=new[]{EquippedArtifacts[0]?.id,EquippedArtifacts[1]?.id},purchased=shopPurchased}));PlayerPrefs.Save();}
  public void EnterHub(){ClearActiveActionSkill();SaveInventory();EnsureOverworldState();IsOverworld=false;ClearRunCheckpoint();shake=0;runDamage=runFire=runVitality=runDash=runChain=runHarvest=0;damageBonus=fireBonus=0;ClearRunUpgradeHistory();shopSellingPage=false;pendingSaleKey=null;ResetGameplayOverlays();ResetArtifactCombat();RefreshPermanentStats();hp=maxHp;RememberOverworldPosition(WorldGeography.Camps[LastVisitedCamp],false);screen=Screen.Hub;BuildHub();}
  public bool EnterDungeon(int index){if(!smoke||index<0||index>HighestUnlocked||index>=3)return false;SelectedStageId=-1;ResetExpeditionMission();DungeonIndex=index;ClearRunUpgradeHistory();ResetArtifactCombat();SaveProgression();StartRun();return true;}
  public bool EnterExpeditionStage(int stageId){if(stageId<0||stageId>=ExpeditionMap.StageCount)return false;if(!smoke&&(!IsOverworld||(WorldGeography.Entrances[stageId]-PlayerPosition).sqrMagnitude>3.5f*3.5f))return false;var stage=ExpeditionMap.Get(stageId,DebtLevel);SelectedStageId=stageId;ResetExpeditionMission();DungeonIndex=stage.legacyDungeonIndex;ClearRunUpgradeHistory();ResetArtifactCombat();SaveProgression();StartRun();return true;}
  public void OnDungeonFinished(bool won){completedRewardGun=null;completedRewardArmor=null;if(won){ExpeditionRunCompleted();if(SelectedExpeditionStage==null||MissionCompleted){HighestUnlocked=Mathf.Min(2,Mathf.Max(HighestUnlocked,DungeonIndex+1));AwardCredits(ScaleScrap(new[]{5000000,10000000,20000000}[DungeonIndex]));if(SelectedStageId>=0){if(clearedExpeditionStages.Contains(SelectedStageId))GrantRepeatExpeditionReward(SelectedStageId);else GrantExpeditionReward(SelectedStageId);}}else Notify("MISSION FAILED / EXTRACTION PAYOUT ONLY","任務失敗 / 脱出報酬のみ");}shopCycle++;shopPurchased.Clear();CreateShopStock();SaveProgression();}
  void GrantExpeditionReward(int stageId)
  {
   if(clearedExpeditionStages.Contains(stageId))return;
   var r=new System.Random(ExpeditionMap.RewardSeed(stageId));int kind=r.Next(4);
   string cacheEn="",cacheJa="";
   switch(kind)
   {
    case 0:
     int scrap=ScaleScrap(25000000+r.Next(250001)*100);AwardCredits(scrap);
     cacheEn="SCRAP +"+scrap.ToString("N0");cacheJa="スクラップ +"+scrap.ToString("N0");break;
    case 1:
     var gear=RollExpeditionGun(r,RollExpeditionRewardRarity(r,true));
     if(StoreWeapon(gear)){completedRewardGun=gear;cacheEn="WEAPON CACHE";cacheJa="銃の報酬箱";}
     else {int salvage=ScaleScrap(40000000);AwardCredits(salvage);cacheEn="SALVAGE +"+salvage.ToString("N0");cacheJa="換金 +"+salvage.ToString("N0");}break;
    case 2:
     var armor=RollExpeditionArmor(r,RollExpeditionRewardRarity(r,true));
     if(StoreArmor(armor)){completedRewardArmor=armor;cacheEn="ARMOR CACHE";cacheJa="防具の報酬箱";}
     else {int salvage=ScaleScrap(40000000);AwardCredits(salvage);cacheEn="SALVAGE +"+salvage.ToString("N0");cacheJa="換金 +"+salvage.ToString("N0");}break;
    default:ExpeditionTokens++;cacheEn="SKILL POINT +1";cacheJa="スキルポイント +1";break;
   }
   int missionScrap=MissionCompleted?TryClaimMissionReward():0;
   clearedExpeditionStages.Add(stageId);SaveProgression();
   string missionEn=missionScrap>0?" / MISSION SCRAP +"+missionScrap.ToString("N0"):"";
   string missionJa=missionScrap>0?" / 任務スクラップ +"+missionScrap.ToString("N0"):"";
   Notify("FIRST CLEAR / "+cacheEn+missionEn,"初回クリア / "+cacheJa+missionJa);
  }
  void GrantRepeatExpeditionReward(int stageId)
  {
   // Replays never award another skill point; choose a repeatable payout.
   var r=new System.Random(unchecked(ExpeditionMap.RewardSeed(stageId) ^ (shopCycle+1)*104729));
   if(r.NextDouble()<.5)
   {
    int scrap=ScaleScrap(14000000+r.Next(120001)*100);AwardCredits(scrap);
    Notify("REPEAT REWARD / SCRAP +"+scrap.ToString("N0"),"再攻略報酬 / スクラップ +"+scrap.ToString("N0"));return;
   }
   bool weapon=r.Next(2)==0;
   Rarity rarity=RollExpeditionRewardRarity(r);
   var repeatGun=weapon?RollExpeditionGun(r,rarity):null;var repeatArmor=weapon?null:RollExpeditionArmor(r,rarity);
   bool stored=weapon?StoreWeapon(repeatGun):StoreArmor(repeatArmor);
   if(stored){completedRewardGun=repeatGun;completedRewardArmor=repeatArmor;}
   if(stored)Notify(weapon?"REPEAT REWARD / WEAPON":"REPEAT REWARD / ARMOR",weapon?"再攻略報酬 / 銃":"再攻略報酬 / 防具");
   else {int salvage=ScaleScrap(18000000);AwardCredits(salvage);Notify("REPEAT REWARD / SALVAGE +"+salvage.ToString("N0"),"再攻略報酬 / 換金 +"+salvage.ToString("N0"));}
  }
  public string ExpeditionRewardDescription(int stageId){if(clearedExpeditionStages.Contains(stageId))return VaultLanguage.T("REPEAT / scrap or gear","再攻略 / スクラップか装備");var r=new System.Random(ExpeditionMap.RewardSeed(stageId));int kind=r.Next(4);if(kind==0){int amount=ScaleScrap(25000000+r.Next(250001)*100);return VaultLanguage.T("SCRAP +"+amount.ToString("N0"),"スクラップ +"+amount.ToString("N0"));}if(kind==1)return VaultLanguage.T("GEAR CACHE / weapon (salvage if full)", "装備箱 / 銃（満杯時は換金）");if(kind==2)return VaultLanguage.T("GEAR CACHE / armor (salvage if full)","装備箱 / 防具（満杯時は換金）");return VaultLanguage.T("SKILL POINT +1 (FIRST CLEAR)","スキルポイント +1（初回のみ）");}
  public void AwardCredits(int amount){Credits=(int)Math.Min(int.MaxValue,(long)Credits+Math.Max(0,amount));SaveProgression();}
  public bool TrySpendCredits(int amount){if(amount<=0||Credits<amount)return false;Credits-=amount;SaveProgression();return true;}
  void CreateShopStock(){shopStock.Clear();var r=new System.Random(51031+shopCycle*7919+HighestUnlocked*173);for(int i=0;i<4;i++){var offer=new ShopOffer();int level=DungeonCatalog.ItemLevel(r,HighestUnlocked);Rarity rarity=VaultBalanceProfile.Current!=null?VaultBalanceProfile.Current.RollShopRarity(r):i==3?Rarity.Rare:Rarity.Uncommon;if(i==0||i==1)offer.gun=Arsenal.CreateForDungeon(r,HighestUnlocked,rarity,level);else if(i==2)offer.armor=Armory.CreateForDungeon(r,HighestUnlocked,rarity,level);else offer.artifact=ArtifactCatalog.Create(r,HighestUnlocked,rarity,level);offer.cost=Mathf.Clamp((5000+level*300+(int)rarity*3500)*ScrapLevelMultiplier,5000,30000*ScrapLevelMultiplier);offer.purchased=shopPurchased.Contains(i);shopStock.Add(offer);}var melee=new ShopOffer{melee=MeleeWeaponCatalog.Create(r,DungeonCatalog.ItemLevel(r,HighestUnlocked))};melee.cost=(7500+melee.melee.level*800)*ScrapLevelMultiplier;melee.purchased=shopPurchased.Contains(4);shopStock.Add(melee);}
  public bool PurchaseShop(int index){if(index<0||index>=shopStock.Count)return false;var o=shopStock[index];int price=ShopOfferPrice(o);if(o.purchased||Credits<price||o.armor!=null&&!Armory.IsActiveArmor(o.armor))return false;bool stored=o.gun!=null?StoreWeapon(o.gun):o.armor!=null?StoreArmor(o.armor):o.artifact!=null?StoreArtifact(o.artifact):StoreMeleeWeapon(o.melee);if(!stored){Notify("Storage full. Discard unused equipment.","所持枠が満杯です。不要な装備を整理してください。");return false;}Credits-=price;o.purchased=true;shopPurchased.Add(index);SaveProgression();return true;}
  public bool StoreArtifact(ArtifactItem a){if(a==null||ArtifactInventory.Count>=ArtifactCapacity)return false;if(!ArtifactInventory.Contains(a))ArtifactInventory.Add(a);SaveProgression();return true;}
  public void EquipArtifact(ArtifactItem a,int slot){if(slot<0||slot>1||!ArtifactInventory.Contains(a))return;for(int i=0;i<2;i++)if(EquippedArtifacts[i]==a)EquippedArtifacts[i]=null;var displaced=EquippedArtifacts[slot];if(displaced!=null&&displaced!=a)reloadSurgeExpiry.Remove(displaced.id);EquippedArtifacts[slot]=a;RefreshReloadSurgeSummary();RecalculateArmor();SaveProgression();}
  public void UnequipArtifact(int slot){if(slot<0||slot>1)return;var removed=EquippedArtifacts[slot];if(removed!=null)reloadSurgeExpiry.Remove(removed.id);EquippedArtifacts[slot]=null;RefreshReloadSurgeSummary();RecalculateArmor();SaveProgression();}
  public void DiscardArtifact(ArtifactItem a){if(Array.IndexOf(EquippedArtifacts,a)>=0)return;if(a==null)return;ArtifactInventory.Remove(a);reloadSurgeExpiry.Remove(a.id);artifactTimers.Remove(a.id);RefreshReloadSurgeSummary();SaveProgression();}
  public void ResetArtifactCombat(){ResetLegendaryEffects();ArtifactShield=0;reloadSurge=0;artifactCombatClock=0;reloadSurgeExpiry.Clear();armorKillTimer=0;armorDashTimer=0;artifactTimers.Clear();}
  public void TickArtifacts(float dt){TickLegendaryEffects(dt);ArtifactShield=Mathf.Max(0,ArtifactShield-dt*2);artifactCombatClock+=Mathf.Max(0,dt);RefreshReloadSurgeSummary();UpdateBarrierVisual();armorKillTimer=Mathf.Max(0,armorKillTimer-dt);armorDashTimer=Mathf.Max(0,armorDashTimer-dt);foreach(var key in new List<string>(artifactTimers.Keys))artifactTimers[key]=Mathf.Max(0,artifactTimers[key]-dt);if(Active&&dt>0&&ArtifactShield>0)foreach(var a in EquippedArtifacts)if(a!=null&&!string.IsNullOrEmpty(a.id)&&a.effect==ArtifactEffect.ShieldConversion&&ArtifactTimer(a)<=0&&ArtifactCatalog.LegendaryModuleBonus(a,out _,out _,out _)){ActivateLegendaryModule(a);artifactTimers[a.id]=5;}}
  public float ArtifactReloadSurgeRemaining(ArtifactItem a)=>a!=null&&a.effect==ArtifactEffect.ReloadSurge&&!string.IsNullOrEmpty(a.id)&&reloadSurgeExpiry.TryGetValue(a.id,out float expiry)?Mathf.Max(0,expiry-artifactCombatClock):0;
  void RefreshReloadSurgeSummary(){reloadSurge=0;foreach(var a in EquippedArtifacts)if(a!=null)reloadSurge=Mathf.Max(reloadSurge,ArtifactReloadSurgeRemaining(a));}
  public float ArtifactDamageMultiplier{get{float bonus=0;foreach(var a in EquippedArtifacts)if(a!=null){if(a.effect==ArtifactEffect.ReloadSurge&&ArtifactReloadSurgeRemaining(a)>0)bonus+=.15f*a.power;if(a.effect==ArtifactEffect.ShieldConversion&&ArtifactShield>0)bonus+=.12f*a.power;}foreach(var armor in EquippedArmor)if(Armory.IsActiveArmor(armor)&&armor.uniqueEffect==3&&ArtifactShield>0){bonus+=.15f;break;}return 1+bonus;}}
  public float AbsorbArtifactDamage(float damage){if(damage<=0||ArtifactShield<=0)return damage;float reduction=Mathf.Min(.75f,.25f+Mathf.Min(.20f,ArtifactShield*.005f)+Mathf.Min(.15f,ArtifactAffixBonus("mitigation"))+Mathf.Min(.10f,DebtDamageReductionBonus*.5f));ArtifactShield=Mathf.Max(0,ArtifactShield-Mathf.Min(ArtifactShield,damage));return damage*(1-reduction);}
  void ActivateLegendaryModule(ArtifactItem a)
  {
   if(!ArtifactCatalog.LegendaryModuleBonus(a,out int healing,out int rounds,out float dodge))return;
   hp=Mathf.Min(maxHp,hp+healing);dodgeCooldown=Mathf.Max(0,dodgeCooldown-dodge);
   if(rounds>0&&gun!=null){var type=AmmoForGun(gun);ammoReserves[(int)type]=Mathf.Min(AmmoCapacity(type),ammoReserves[(int)type]+rounds);}
   ApplyLegendaryModuleSignature(a);
  }
  public void ArtifactOnKill(Vector3 position){if(armorKillTimer<=0){foreach(var armor in EquippedArmor)if(Armory.IsActiveArmor(armor)&&armor.uniqueEffect==1){ArtifactShield=Mathf.Max(ArtifactShield,Mathf.Min(30,ArtifactShield+4));armorKillTimer=4;break;}}for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a==null||ArtifactTimer(a)>0||a.effect!=ArtifactEffect.KillShield)continue;ArtifactShield=Mathf.Max(ArtifactShield,Mathf.Min(30,ArtifactShield+8*a.power));artifactTimers[a.id]=a.cooldown;ActivateLegendaryModule(a);}}
  public void ArtifactOnReload(){LegendaryTrigger("reload",PlayerPosition);for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a!=null&&ArtifactTimer(a)<=0&&a.effect==ArtifactEffect.ReloadSurge){reloadSurgeExpiry[a.id]=artifactCombatClock+3;artifactTimers[a.id]=a.cooldown;ActivateLegendaryModule(a);}}RefreshReloadSurgeSummary();}
  public void ArtifactOnDash(){LegendaryTrigger("dash",PlayerPosition);if(armorDashTimer<=0){foreach(var armor in EquippedArmor)if(Armory.IsActiveArmor(armor)&&armor.uniqueEffect==2){hp=Mathf.Min(maxHp,hp+4);armorDashTimer=5;break;}}for(int i=0;i<2;i++){var a=EquippedArtifacts[i];if(a==null||ArtifactTimer(a)>0||a.effect!=ArtifactEffect.DashPulse)continue;artifactTimers[a.id]=a.cooldown;foreach(var f in Enemies.ToArray())if(f!=null&&Vector3.Distance(f.transform.position,PlayerPosition)<3.5f)f.Hit(12*a.power,null,new Color(1,.22f,.16f));Burst(PlayerPosition,Cyan,12);ActivateLegendaryModule(a);}}
  class ArtifactDrop{public ArtifactItem item;public Vector3 position;public GameObject visual;}
  readonly List<ArtifactDrop> artifactDrops=new List<ArtifactDrop>();
  ArtifactDrop NearArtifact(){ArtifactDrop nearest=null;float distance=2.6f;foreach(var d in artifactDrops){float n=Vector3.Distance(PlayerPosition,d.position);if(n<distance){nearest=d;distance=n;}}return nearest;}
  public ArtifactItem NearbyArtifact=>NearArtifact()?.item;
  public void AddArtifactDrop(ArtifactItem item,Vector3 position){if(item==null)return;position.y=.5f;var visual=CreateLootPresentation(item.Name,position,new Vector3(.45f,.3f,.55f),Arsenal.Colors[(int)item.rarity],LootPresentationKind.Module,rarity:item.rarity);ApplyProductDropModel(visual,item);artifactDrops.Add(new ArtifactDrop{item=item,position=position,visual=visual});}
  public void ClearArtifactDrops(){foreach(var d in artifactDrops)if(d.visual!=null)Destroy(d.visual);artifactDrops.Clear();}
  public bool PickupArtifactNearest(){var d=NearArtifact();if(d==null)return false;float distance=Vector3.Distance(PlayerPosition,d.position);var weapon=NearDrop();var armor=NearArmor();if(weapon!=null&&Vector3.Distance(PlayerPosition,weapon.position)<distance)return false;if(armor!=null&&Vector3.Distance(PlayerPosition,armor.position)<distance)return false;if(!StoreArtifact(d.item)){Notify("Artifact storage full. Discard unused artifacts in [I].","拡張モジュール枠が満杯です。[I]で整理してください。");return true;}artifactDrops.Remove(d);Destroy(d.visual);Notify(ArtifactCatalog.DisplayName(d.item,false)+" collected.",ArtifactCatalog.DisplayName(d.item,true)+"を入手");return true;}
