  public int ShopOfferPrice(ShopOffer offer)
  {
   if(offer==null)return 0;
   int sale=offer.gun!=null?SaleValue(offer.gun):offer.armor!=null?SaleValue(offer.armor):offer.artifact!=null?SaleValue(offer.artifact):offer.melee!=null?SaleValue(offer.melee):0;
   return (int)Math.Min(int.MaxValue,(long)sale*10);
  }
